/* Platform logos: Simple Icons (CC0), white on the platform colour */
Object.entries(PLATFORMS).forEach(([k,v])=>{ v.key = k; });
const pgm = (m, cls="") => { const d = LOGOS[m.key]; return `<span class="pg ${cls} ${d?"logo":""}" style="--pc:${m.c}" title="${esc(m.label)}">${d?`<svg viewBox="0 0 24 24" aria-hidden="true" style="fill:${lightBg(m.c)?"#111":"#fff"}"><path d="${d}"/></svg>`:esc(m.g)}</span>`; };
function lightBg(hex){ const h=/^#?([0-9a-f]{6})$/i.exec(hex||""); if(!h) return false; const n=parseInt(h[1],16), r=n>>16, g=n>>8&255, b=n&255; return (0.299*r+0.587*g+0.114*b) > 175; }
const pg = (k, cls="") => pgm(pf(k), cls);
const handleOf = (b, c) => c?.handle ? (/^[@#r\/]|[.\s]/.test(c.handle) ? c.handle : "@"+c.handle) : (b?.name||"");
const uid = () => Math.random().toString(36).slice(2,8);
function postMeta(p){ const b=brandById(p.brandId), c=chanOf(b,p.channelId); return c ? cmeta(c) : pf(p.platform); }

function ymd(d){ return d.getFullYear()+"-"+String(d.getMonth()+1).padStart(2,"0")+"-"+String(d.getDate()).padStart(2,"0"); }
function parseYmd(s){ if(!s) return null; const [y,m,d]=s.split("-").map(Number); return new Date(y,m-1,d); }
function weekStart(o){ const d=new Date(); d.setHours(0,0,0,0); d.setDate(d.getDate()-((d.getDay()+6)%7)+o*7); return d; }
function weekDays(o){ const s=weekStart(o); return Array.from({length:7},(_,i)=>{const d=new Date(s); d.setDate(s.getDate()+i); return d;}); }
function fmtDate(s){ const d=parseYmd(s); return d ? d.toLocaleDateString(undefined,{day:"numeric",month:"short"}) : ""; }
const todayStr = () => ymd(new Date());
function toast(msg){ const t=$("toast"); t.textContent=msg; t.hidden=false; clearTimeout(toast._t); toast._t=setTimeout(()=>t.hidden=true,2600); }
function opts(list, sel){ return list.map(([v,l])=>`<option value="${esc(v)}" ${v===sel?"selected":""}>${esc(l)}</option>`).join(""); }
function platformSelect(sel, attrs=""){
  return `<select ${attrs}>${CATS.map(cat=>`<optgroup label="${esc(cat)}">${PF_ORDER.filter(k=>pf(k).cat===cat).map(k=>`<option value="${k}" ${k===sel?"selected":""}>${esc(pf(k).label)}</option>`).join("")}</optgroup>`).join("")}<optgroup label="Custom"><option value="custom" ${sel==="custom"?"selected":""}>Custom channel…</option></optgroup></select>`;
}

/* ================= filtering ================= */
function inScope(brandId){ if(S.brand) return brandId===S.brand; if(S.group==="all") return true; const b=brandById(brandId); return !!b && (b.group||"Other")===S.group; }
function brandVisible(b){ return inScope(b.id) && (S.platform==="all" || chans(b).some(c=>colKey(c)===S.platform)); }
function visibleBrands(){ return S.brands.filter(brandVisible); }
function visiblePosts(){
  return S.posts.filter(p => {
    if (S.brand) return p.brandId === S.brand;
    const b = brandById(p.brandId);
    if (S.group!=="all" && (!b || (b.group||"Other")!==S.group)) return false;
    if (S.platform!=="all"){ const c=chanOf(b,p.channelId); if(!c || colKey(c)!==S.platform) return false; }
    return true;
  });
}
const thisWeek = () => weekDays(0).map(ymd);
function shots(brandId, channelId, days){ return S.posts.filter(p=>p.brandId===brandId && p.channelId===channelId && (p.status==="posted"||p.status==="scheduled") && days.includes(p.date)).length; }
const dumpsOf = id => S.dumps.filter(d=>d.brandId===id).sort((a,b)=>(b.createdAt||0)-(a.createdAt||0));

/* ================= render ================= */
function render(){ renderStats(); renderChips(); renderFire(); renderWeek(); renderBoard(); renderBrands(); renderMods(); if(typeof renderMap==="function") renderMap(); if(typeof mmRender==="function") mmRender(); }

function renderStats(){
  const days = thisWeek();
  const live = S.brands.filter(b=>b.status!=="paused" && inScope(b.id));
  const nCh = live.reduce((n,b)=>n+chans(b).length,0);
  const target = live.reduce((n,b)=>n+chans(b).reduce((m,c)=>m+(+c.cadence||0),0),0);
  const fired = S.posts.filter(p=>inScope(p.brandId) && (p.status==="posted"||p.status==="scheduled") && days.includes(p.date)).length;
  const ideas = S.posts.filter(p=>inScope(p.brandId) && p.status==="idea").length;
  const voiced = live.filter(b=>b.brain?.summary).length;
  $("stats").innerHTML = [
    ["Brands", live.length, `${voiced} with a brand brain`],
    ["Channels", nCh, `${new Set(live.flatMap(b=>chans(b).map(colKey))).size} platforms`],
    ["Shots this week", fired, target ? `of ${target} targeted, posted or scheduled` : "set targets per channel"],
    ["Ammo", ideas, `ideas · ${S.dumps.filter(d=>!d.used && inScope(d.brandId)).length} raw dumps waiting`]
  ].map(([l,v,s])=>`<div class="stat"><span class="eyebrow">${l}</span><b>${v}</b><span class="muted" style="font-size:12px">${esc(s)}</span></div>`).join("");
}

function uiGet(k, d){ try{ const v = localStorage.getItem("dist_"+k); return v==null ? d : JSON.parse(v); }catch(_){ return d; } }
function uiSet(k, v){ try{ localStorage.setItem("dist_"+k, JSON.stringify(v)); }catch(_){} }
document.addEventListener("click", e => { if(e.target.closest("#pfToggle")){ uiSet("pfOpen", !uiGet("pfOpen", false)); renderChips(); } });
/* collapsible sections: the section heading toggles its body */
function setupCollapsibles(){
  document.querySelectorAll("section[data-col]").forEach(sec => {
    const head = sec.querySelector(".sec-head"), h2 = head?.querySelector("h2"); if(!h2 || h2.dataset.wired) return;
    h2.dataset.wired = 1; h2.classList.add("col-h"); h2.tabIndex = 0; h2.setAttribute("role","button");
    h2.insertAdjacentHTML("afterbegin", `<span class="chev">▾</span> `);
    const body = [...sec.children].filter(x=>x!==head);
    const apply = open => { body.forEach(x=>x.hidden=!open); sec.classList.toggle("collapsed", !open); h2.setAttribute("aria-expanded", open); };
    apply(!uiGet("col_"+sec.dataset.col, false));
    const toggle = () => { const open = sec.classList.contains("collapsed"); uiSet("col_"+sec.dataset.col, !open); apply(open); };
    h2.onclick = toggle; h2.onkeydown = e => { if(e.key==="Enter"||e.key===" "){ e.preventDefault(); toggle(); } };
  });
  document.querySelectorAll(".colbox").forEach(box => {
    const t = box.querySelector(".col-t"), b = box.querySelector(".col-b"); if(t.dataset.wired) return; t.dataset.wired = 1;
    const apply = open => { b.hidden = !open; t.setAttribute("aria-expanded", open); box.classList.toggle("collapsed", !open); };
    apply(!uiGet("col_"+box.dataset.col, false));
    t.onclick = () => { const open = box.classList.contains("collapsed"); uiSet("col_"+box.dataset.col, !open); apply(open); };
  });
}
/* top-level views */
const VIEWS = ["memory","map","overview","calendar","brands","analytics","ads","messages"];
function showView(v){
  if(!VIEWS.includes(v)) v = "brands";
  document.querySelectorAll("[data-view]").forEach(b=>b.setAttribute("aria-selected", b.dataset.view===v));
  document.querySelectorAll("[data-viewpane]").forEach(x=>x.hidden = x.dataset.viewpane!==v);
  if(v==="map") renderMap(); if(v==="memory") mmRender(); if(v==="memories" && window.memOpen) memOpen();
}
document.querySelectorAll("[data-view]").forEach(b => b.onclick = () => { if(location.hash.slice(1)!==b.dataset.view) location.hash = b.dataset.view; else showView(b.dataset.view); });
window.addEventListener("hashchange", () => showView(location.hash.slice(1)));

/* ===== brand switcher: one scope for every tab ===== */
function setScope(brand, group){ S.brand = brand||null; S.group = brand ? "all" : (group||"all"); uiSet("scope", {brand:S.brand, group:S.group}); closeSwitcher(); render(); }
function renderSwitcher(groups){
  const btn=$("bswBtn"); if(!btn) return; const b=S.brand&&brandById(S.brand);
  if(S.brand && !b && S.gotB){ S.brand=null; }
  const label = b ? `${mono(b,"sm")}<span class="bsw-t"><b>${esc(b.name)}</b><small>${esc(b.group||"")} · tap to switch</small></span>`
    : `<span class="bsw-all">★</span><span class="bsw-t"><b>Pick a brand</b><small>Showing ${S.group==="all"?"all "+S.brands.length:esc(S.group)}</small></span>`;
  btn.innerHTML = label + `<span class="chev">▾</span>`;
  btn._groups = groups;
  if(!$("bswPop").hidden) fillSwitcher();
}
function fillSwitcher(){
  const q=$("bswQ").value.trim().toLowerCase(), groups=$("bswBtn")._groups||GROUPS;
  const row = (attrs, icon, name, sub, on) => `<button class="bsw-i" role="option" aria-selected="${on}" ${attrs}>${icon}<span class="bsw-t"><b>${name}</b>${sub?`<small>${sub}</small>`:""}</span>${on?"<span class=\"ok\">✓</span>":""}</button>`;
  let html = q ? "" : row('data-scope="all"', `<span class="bsw-all">★</span>`, "All brands", `${S.brands.length} brands`, !S.brand && S.group==="all");
  groups.forEach(g => {
    const list = S.brands.filter(b=>(b.group||"Other")===g && (!q || b.name.toLowerCase().includes(q) || (b.industry||"").toLowerCase().includes(q))).sort((a,b)=>(a.order??999)-(b.order??999)||a.name.localeCompare(b.name));
    if(!list.length) return;
    html += `<div class="bsw-g"><span>${esc(g)}</span>${q?"":`<button class="lnk" data-scopeg="${esc(g)}" ${!S.brand&&S.group===g?"aria-pressed=\"true\"":""}>All ${list.length}</button>`}</div>`;
    html += list.map(b=>row(`data-scopeb="${esc(b.id)}"`, mono(b,"sm"), esc(b.name), esc(b.industry||""), S.brand===b.id)).join("");
  });
  $("bswList").innerHTML = html || `<div class="muted" style="padding:10px;font-size:13px">No brand matches.</div>`;
}
function openSwitcher(){ $("bswPop").hidden=false; $("bswBtn").setAttribute("aria-expanded","true"); $("bswQ").value=""; fillSwitcher(); setTimeout(()=>$("bswQ").focus(),0); }
function closeSwitcher(){ const p=$("bswPop"); if(p&&!p.hidden){ p.hidden=true; $("bswBtn").setAttribute("aria-expanded","false"); } }
$("bswBtn").onclick = () => $("bswPop").hidden ? openSwitcher() : closeSwitcher();
$("bswQ").oninput = fillSwitcher;
$("bswQ").onkeydown = e => { if(e.key==="Enter"){ const f=$("bswList").querySelector("[data-scopeb],[data-scope]"); if(f) f.click(); } if(e.key==="Escape") closeSwitcher(); };
$("bswList").onclick = e => { const t=e.target.closest("[data-scopeb],[data-scope],[data-scopeg]"); if(!t) return; if(t.dataset.scopeb) setScope(t.dataset.scopeb); else if(t.dataset.scopeg) setScope(null, t.dataset.scopeg); else setScope(null,"all"); };
document.addEventListener("click", e => { if(!e.target.closest("#bsw")) closeSwitcher(); });
document.addEventListener("keydown", e => { if(e.key==="Escape") closeSwitcher(); });
{ const sc = uiGet("scope", null); if(sc){ S.brand = sc.brand||null; S.group = sc.group||"all"; } }

/* ===== Link → video analysis (first input) ===== */
async function analyseLink(){
  const url = normUrl($("lbUrl").value); const out=$("lbOut");
  if(!url) return toast("Paste a video link first");
  if(!S.sample) return toast("Add your Claude API key in ⚙ Settings to use Claude");
  $("lbGo").disabled=true; out.hidden=false; out.innerHTML=`<div class="ana-card"><span class="status-line">✦ Reading the video page…</span></div>`;
  let page=""; try{ if(await browserReady()) page = await readLink(url); }catch(_){}
  const id = "a_"+srcKey(url).slice(0,80);
  if(S.db){ try{ const prev=S.analyses?.[id]; if(!prev || prev.status==="failed") await S.db.collection("analyses").doc(id).set({url, status:"queued", requestedAt:Date.now()}); }catch(_){} }
  out.innerHTML=`<div class="ana-card"><span class="status-line">✦ Claude is breaking it down…</span></div>`;
  try{
    const a = await S.sample.json(`You are a short-form video strategist. Break down this video so a team can recreate its formula for other brands (never copy it 1:1).
URL: ${url}
${page?`Text from the video page (caption, stats, comments, transcript if any):\n${page.slice(0,6000)}`:"Only the URL is available, so infer from the platform and URL, and say so in 'confidence'."}
Available edit styles: ${JSON.stringify(styleNames())}
Reply with only JSON: {"title":"what the video is, 6-10 words","platform":"","stats":"views/likes if visible else ''","lengthSec":number|null,"hook":"what happens in the first 2 seconds and why it stops the scroll","beats":[{"t":"0-2s","what":"..."}],"pacing":"cut speed and rhythm","audio":"music/voice","text":"on-screen text and caption style","why":["3 short reasons it works"],"style":"closest style from the list","brief":"a reusable Hook / brief (3-5 lines) that a brand can follow: hook pattern with a blank, body beats, payoff, ending CTA","confidence":"high|medium|low with a few words why"}`, {modelTier:"default"});
    renderAnalysis(url, a);
  }catch(_){ out.innerHTML=`<div class="ana-card"><span class="status-line">Claude couldn't read that link. Try again, or paste the caption with the link.</span></div>`; }
  $("lbGo").disabled=false;
}
function renderAnalysis(url, a){
  const out=$("lbOut"); S.lastAnalysis={url, ...a};
  const deep = S.analyses?.["a_"+srcKey(url).slice(0,80)];
  out.innerHTML = `<div class="ana-card">
    <div class="ana-h"><div><b>${esc(a.title||"Video breakdown")}</b><small>${esc([a.platform,a.stats,a.lengthSec?a.lengthSec+"s":"",a.style].filter(Boolean).join(" · "))}</small></div><button class="btn ghost sm" id="lbClose" aria-label="Close">✕</button></div>
    <div class="ana-hook"><span>Hook</span>${esc(a.hook||"")}</div>
    ${(a.beats||[]).length?`<div class="ana-beats">${a.beats.slice(0,6).map(x=>`<div><b>${esc(x.t||"")}</b>${esc(x.what||"")}</div>`).join("")}</div>`:""}
    <div class="ana-meta">${a.pacing?`<span>✂️ ${esc(a.pacing)}</span>`:""}${a.audio?`<span>🎵 ${esc(a.audio)}</span>`:""}${a.text?`<span>🔤 ${esc(a.text)}</span>`:""}</div>
    ${(a.why||[]).length?`<ul class="ana-why">${a.why.slice(0,4).map(w=>`<li>${esc(w)}</li>`).join("")}</ul>`:""}
    <div class="field full"><label for="lbBrief">Hook / brief for your videos</label><textarea id="lbBrief" style="min-height:76px">${esc(a.brief||"")}</textarea></div>
    <div class="ana-act"><button class="btn fire" id="lbMake">⚡ Make it for my brands</button><span class="status-line">${deep?.status==="done"?"✓ The frame-by-frame breakdown is in.":""} ${a.confidence&&!/^high/i.test(a.confidence)?"Quick read: "+esc(a.confidence):""}</span></div></div>`;
  $("lbClose").onclick=()=>{ out.hidden=true; out.innerHTML=""; };
  $("lbMake").onclick=()=>bulkPanel({brief:$("lbBrief").value.trim(), style:a.style});
}
$("lbGo").onclick = analyseLink;
$("lbUrl").onkeydown = e => { if(e.key==="Enter") analyseLink(); };
function renderChips(){
  const groups = GROUPS.filter(g=>S.brands.some(b=>(b.group||"Other")===g));
  renderSwitcher(groups);
  $("groupChips").innerHTML = [["all","All brands",S.brands.length],...groups.map(g=>[g,g,S.brands.filter(b=>(b.group||"Other")===g).length])]
    .map(([k,l,n])=>`<button class="chip" data-group="${esc(k)}" aria-pressed="${!S.brand&&S.group===k}">${esc(l)}<span class="n">${n}</span></button>`).join("");
  const seen = new Map();
  S.brands.forEach(b=>chans(b).forEach(c=>{ const k=colKey(c); if(!seen.has(k)) seen.set(k,cmeta(c)); }));
  const keys = [...seen.keys()].sort((a,b)=>(PF_ORDER.indexOf(a)+1||999)-(PF_ORDER.indexOf(b)+1||999));
  const open = uiGet("pfOpen", false), sel = S.platform!=="all" && seen.has(S.platform);
  $("pfChips").innerHTML = `<button class="chip pf-toggle" id="pfToggle" aria-expanded="${open}">${open?"▾":"▸"} ${S.platform==="all"?"All platforms":"Platform"} <span class="n">${keys.length}</span></button>`
    + (open ? [`<button class="chip" data-pf="all" aria-pressed="${S.platform==="all"}">All</button>`,...keys.map(k=>`<button class="chip" data-pf="${esc(k)}" aria-pressed="${S.platform===k}">${pgm(seen.get(k))}${esc(seen.get(k).label)}</button>`)].join("")
      : (sel ? `<button class="chip" data-pf="all" aria-pressed="true">${pgm(seen.get(S.platform))}${esc(seen.get(S.platform).label)} ✕</button>` : ""))
    ;
}

function renderFire(){
  const list = visibleBrands(), days = thisWeek();
  const meta = new Map();
  list.forEach(b=>chans(b).forEach(c=>{ const k=colKey(c); if(!meta.has(k)) meta.set(k,cmeta(c)); }));
  ["instagram","linkedin","youtube"].forEach(k=>{ if(!meta.has(k)) meta.set(k,pf(k)); });
  let cols = [...meta.keys()];
  if (S.platform!=="all") cols = [S.platform];
  cols.sort((a,b)=>(PF_ORDER.indexOf(a)+1||999)-(PF_ORDER.indexOf(b)+1||999));
  if (!S.brands.length){ $("fire").innerHTML = `<tbody><tr><td class="muted" style="text-align:left;padding:16px">${S.gotB?"No brands yet. Add a brand, then give it channels.":"Loading your brands…"}</td></tr></tbody>`; return; }
  const head = `<thead><tr><th class="brand">Brand</th>${cols.map(k=>`<th>${pgm(meta.get(k)||pf(k))}${esc((meta.get(k)||pf(k)).label)}</th>`).join("")}<th class="addcol"><button class="btn sm" data-addcolumn>+ Channel</button></th><th>Week</th></tr></thead>`;
  const groups = GROUPS.filter(g=>list.some(b=>(b.group||"Other")===g));
  const body = groups.map(g => {
    const rows = list.filter(b=>(b.group||"Other")===g).sort((a,b)=>(a.order??999)-(b.order??999)||a.name.localeCompare(b.name));
    return `<tr class="grp"><td class="brand">${esc(g)}</td><td colspan="${cols.length+2}"></td></tr>` + rows.map(b => {
      let tot=0, tgt=0;
      const cells = cols.map(k => {
        const cs = chans(b).filter(c=>colKey(c)===k);
        if (!cs.length) return `<td><button class="addch" data-addch="${b.id}" data-p="${esc(k.startsWith("custom:")?"custom":k)}" data-label="${esc(k.startsWith("custom:")?(meta.get(k)?.label||""):"")}" aria-label="Open ${esc((meta.get(k)||pf(k)).label)} for ${esc(b.name)}">+</button></td>`;
        return `<td>${cs.map(c => {
          const n = shots(b.id,c.id,days), t = +c.cadence||0; tot+=n; tgt+=t;
          const ammo = Array.from({length:Math.min(Math.max(t,n,1),10)},(_,i)=>`<i class="${i<n?"f":""}"></i>`).join("");
          return `<button class="cell ${t?(n>=t?"hit":"behind"):""}" style="${bvars(b)}" data-fire="${b.id}" data-ch="${c.id}" title="${esc(handleOf(b,c))}: ${n}${t?` of ${t}`:""} this week"><b>${n}${t?`/${t}`:""}</b><span class="ammo">${ammo}</span></button>`;
        }).join(" ")}</td>`;
      }).join("");
      const st = b.status && b.status!=="active" ? ` <span class="status-pill ${b.status}">${esc((BSTATUS.find(x=>x[0]===b.status)||[])[1]||b.status)}</span>` : "";
      const extra = chans(b).filter(c=>!cols.includes(colKey(c))).length;
      return `<tr><td class="brand"><button class="bname" data-editbrand="${b.id}">${mono(b)}<div style="min-width:0"><span>${esc(b.name)}</span>${st}<small>${esc(b.industry||"")}${b.brain?.summary?" · ✦ brain":""}</small></div></button></td>${cells}<td>${extra?`<span class="muted" style="font-size:11.5px">+${extra} more</span>`:""}</td><td class="rowtot">${tot}${tgt?`/${tgt}`:""}</td></tr>`;
    }).join("");
  }).join("");
  $("fire").innerHTML = head + `<tbody>${body || `<tr><td class="muted" colspan="${cols.length+3}" style="text-align:left;padding:16px">No brands match these filters.</td></tr>`}</tbody>`;
}

function renderBrands(){
  const list = visibleBrands().sort((a,b)=>GROUPS.indexOf(a.group||"Other")-GROUPS.indexOf(b.group||"Other")||(a.order??999)-(b.order??999));
  $("brands").innerHTML = list.map(b => { const nd = dumpsOf(b.id).filter(d=>!d.used).length, br=b.brain||{};
    const cs = chans(b), CAP = 14;
    const bn = /^\/_blob\/[A-Za-z0-9]+$/.test(b.banner||"") ? b.banner : "";
    return `<div class="bcard ${S.brand===b.id?"sel":""}" style="${bvars(b)}">${bn?`<div class="bc-ban" style="background-image:url('${bn}')"></div>`:""}
      <div class="bc-h">${mono(b)}<div style="min-width:0"><strong>${esc(b.name)}</strong><span class="ind">${esc(b.industry||b.group||"")}</span></div></div>
      <div class="bbody"><p>${esc(br.summary||b.tagline||"")}</p>
        ${br.personality?.length?`<div class="traits">${br.personality.slice(0,3).map(t=>`<span>${esc(t)}</span>`).join("")}</div>`:""}
        <div class="bc-ch">${cs.slice(0,CAP).map(c=>`<span class="bc-i" title="${esc(cmeta(c).label+(c.handle?" · "+handleOf(b,c):""))}">${pgm(cmeta(c))}</span>`).join("")}${cs.length>CAP?`<button class="bc-more" data-hub="${b.id}" data-tab="channels">+${cs.length-CAP}</button>`:""}${cs.length?`<span class="bc-n">${cs.length} channel${cs.length>1?"s":""}</span>`:`<span class="muted" style="font-size:12px">No channels yet</span>`}</div>
      </div>
      <div class="bfoot"><button class="btn sm" data-editbrand="${b.id}">Open hub</button><button class="btn sm ghost" data-hub="${b.id}" data-tab="dump">Dump${nd?` · ${nd}`:""}</button><button class="btn sm ghost" data-focus="${b.id}">${S.brand===b.id?"All brands":"Switch to"}</button></div>
    </div>`; }).join("") + `<button class="bcard" data-addbrand style="border-style:dashed;display:grid;place-items:center;min-height:180px;color:var(--muted);background:transparent">+ Add brand</button>`;
}

S.calMode = (()=>{ try{ return localStorage.getItem("dist_calMode")||"month"; }catch(_){ return "month"; } })();
S.monthOffset = 0;
function calChip(p){ const b=brandById(p.brandId), m=postMeta(p);
  return `<button class="cal-chip st-${p.status||"idea"}" draggable="true" style="${bvars(b)}" data-open="${p.id}" data-cid="${p.id}" title="${esc((b?.name||"")+" · "+m.label+" · "+p.title)}">${pgm(m)}<span>${esc(p.title)}</span></button>`; }
function renderWeek(){
  const t = todayStr(), posts = visiblePosts(), mode = S.calMode;
  document.querySelectorAll('input[name="calMode"]').forEach(r=>r.checked = r.value===mode);
  let days, title, month = -1;
  if(mode==="month"){
    const now = new Date(), first = new Date(now.getFullYear(), now.getMonth()+S.monthOffset, 1); month = first.getMonth();
    const start = new Date(first); start.setDate(1 - ((first.getDay()+6)%7));
    const last = new Date(first.getFullYear(), first.getMonth()+1, 0), cells = Math.ceil((((first.getDay()+6)%7) + last.getDate())/7)*7;
    days = Array.from({length:cells},(_,i)=>{ const d=new Date(start); d.setDate(start.getDate()+i); return d; });
    title = first.toLocaleDateString(undefined,{month:"long", year:"numeric"});
  } else {
    days = weekDays(S.weekOffset);
    title = S.weekOffset===0 ? "This week" : `${fmtDate(ymd(days[0]))} – ${fmtDate(ymd(days[6]))}`;
  }
  $("weekTitle").textContent = title;
  const cap = mode==="month" ? 3 : 12, inRange = new Set(days.map(ymd));
  const byDay = {}; posts.forEach(p=>{ if(p.date && inRange.has(p.date)) (byDay[p.date] ||= []).push(p); });
  const undated = posts.filter(p=>!p.date && p.status!=="posted").length;
  const head = mode==="week" ? "" : days.slice(0,7).map(d=>`<div class="cal-dow">${d.toLocaleDateString(undefined,{weekday:"short"})}</div>`).join("");
  $("week").className = "cal "+mode;
  $("week").innerHTML = head + days.map(d => {
    const k = ymd(d), items = (byDay[k]||[]).sort((a,b)=>STAGES.findIndex(s=>s.id===a.status)-STAGES.findIndex(s=>s.id===b.status));
    const out = mode==="month" && d.getMonth()!==month;
    return `<div class="cal-cell ${k===t?"today":""} ${out?"out":""} ${k<t?"past":""}" data-day="${k}">
      <div class="cal-d"><span class="cal-n">${mode==="week"?`${d.toLocaleDateString(undefined,{weekday:"short"})} `:""}${d.getDate()}</span>${items.length?`<span class="cal-c">${items.length}</span>`:""}<button class="cal-add" data-addday="${k}" aria-label="Add post on ${fmtDate(k)}">+</button></div>
      <div class="cal-items">${items.slice(0,cap).map(calChip).join("")}${items.length>cap?`<button class="cal-more" data-dayall="${k}">+${items.length-cap} more</button>`:""}</div>
      <div class="cal-dots">${items.slice(0,6).map(p=>`<i style="${bvars(brandById(p.brandId))}"></i>`).join("")}</div>
    </div>`;
  }).join("");
  $("calFoot").innerHTML = `<span class="muted">Drag a post to another day to move it. Click a day's + to add one.</span>${undated?`<button class="btn sm ghost" id="calUndated">${undated} post${undated===1?"":"s"} without a date</button>`:""}`;
  if($("calUndated")) $("calUndated").onclick = () => { document.querySelector('section[data-col="pipe"]')?.scrollIntoView({behavior:"smooth"}); };
}
function dayPanel(k){
  const items = visiblePosts().filter(p=>p.date===k);
  openPanel(`<div class="panel-h"><h2>${esc(parseYmd(k).toLocaleDateString(undefined,{weekday:"long", day:"numeric", month:"long"}))}</h2><button class="btn ghost" data-close aria-label="Close">✕</button></div>
    <div class="cal-list">${items.map(calChip).join("")}</div><div><button class="btn primary sm" data-addday="${k}">+ Add post on this day</button></div>`);
}
document.addEventListener("click", e => {
  const add = e.target.closest("[data-addday]"); if(add){ e.stopPropagation(); return postPanel(null,{date:add.dataset.addday, status:"scheduled"}); }
  const all = e.target.closest("[data-dayall]"); if(all) return dayPanel(all.dataset.dayall);
  const dot = e.target.closest(".cal.month .cal-cell"); if(dot && window.matchMedia("(max-width:640px)").matches && !e.target.closest("[data-open]")) return dayPanel(dot.dataset.day);
});
document.addEventListener("change", e => { if(e.target.name==="calMode"){ S.calMode = e.target.value; try{ localStorage.setItem("dist_calMode", S.calMode); }catch(_){} renderWeek(); } });
let calDrag = null;
document.addEventListener("dragstart", e => { const c=e.target.closest?.(".cal-chip"); if(!c) return; calDrag=c.dataset.cid; c.classList.add("dragging"); try{ e.dataTransfer.setData("text/plain",calDrag); e.dataTransfer.effectAllowed="move"; }catch(_){} });
document.addEventListener("dragend", () => { calDrag=null; document.querySelectorAll(".cal-cell.over,.cal-chip.dragging").forEach(x=>x.classList.remove("over","dragging")); });
document.addEventListener("dragover", e => { const cell=e.target.closest?.(".cal-cell"); if(!cell||!calDrag) return; e.preventDefault(); document.querySelectorAll(".cal-cell.over").forEach(x=>x!==cell&&x.classList.remove("over")); cell.classList.add("over"); });
document.addEventListener("drop", e => { const cell=e.target.closest?.(".cal-cell"); if(!cell||!calDrag) return; e.preventDefault(); cell.classList.remove("over");
  const p=S.posts.find(x=>x.id===calDrag), d=cell.dataset.day; calDrag=null;
  if(p && p.date!==d){ p.date=d; renderWeek(); savePost(p.id,{date:d, ...(p.status==="idea"||p.status==="drafting"?{}:{})}).then(ok=>ok&&toast(`Moved to ${fmtDate(d)}`)); } });

function renderBoard(){
  const posts = visiblePosts(), t = todayStr();
  $("board").innerHTML = STAGES.map((st,i) => {
    let items = posts.filter(p => (p.status||"idea")===st.id); const total = items.length;
    items.sort((a,b)=> st.id==="posted" ? (b.date||"").localeCompare(a.date||"") : ((a.date||"9999").localeCompare(b.date||"9999")) || ((b.updatedAt||0)-(a.updatedAt||0)));
    const lim = S.boardLimit[st.id] || 25; items = items.slice(0, lim);
    return `<div class="col" data-stage="${st.id}">
      <div class="col-h"><strong><span class="st" style="--s:var(--${st.id})"></span>${st.label}</strong><span class="n">${total}</span></div>
      ${items.map(p=>{const b=brandById(p.brandId), c=chanOf(b,p.channelId), late=p.date&&p.date<t&&st.id!=="posted";
        return `<div class="card" style="${bvars(b)}" draggable="true" data-id="${p.id}" tabindex="0" role="button" aria-label="Open ${esc(p.title)}">
          <div class="card-t">${esc(p.title||"Untitled")}</div>
          <div class="card-m">${mono(b,"sm")}${pgm(postMeta(p))}<span>${esc(c?handleOf(b,c):(b?.name||"No brand"))}</span>${p.format?`<span>· ${esc(p.format)}</span>`:""}${p.date?`<span class="date ${late?"late":""}">${fmtDate(p.date)}${late?" · overdue":""}</span>`:""}${p.blastId?`<span class="blast-tag">BLAST</span>`:""}${p.dumpId?`<span class="blast-tag">DUMP</span>`:""}${renderBadge(p.id)}</div>
          ${i<3?`<div class="card-a"><button class="btn sm ghost" data-advance="${p.id}">Move to ${STAGES[i+1].label} →</button></div>`:""}
        </div>`;}).join("") || `<div class="empty-col">${S.gotP?"Nothing here":"Loading…"}</div>`}
      ${total>lim?`<button class="btn sm ghost" data-more="${st.id}">Show ${Math.min(25,total-lim)} more</button>`:""}
    </div>`;
  }).join("");
}

/* ================= writes ================= */
function denied(e){ toast(e?.code==="permission_denied"?"You can view this board but not change it":"Couldn't save. Try again."); return false; }
async function savePost(id, data){
  if(!S.db){ toast("Sign in to save changes"); return false; }
  const body = {...data, updatedAt: Date.now()};
  try{ if(id) await S.db.collection("posts").doc(id).update(body); else await S.db.collection("posts").doc().set({...body, createdAt: Date.now()}); return true; }
  catch(e){ return denied(e); }
}
async function saveBrand(id, data){
  if(!S.db){ toast("Sign in to save changes"); return false; }
  try{ if(id) await S.db.collection("brands").doc(id).set({...data, updatedAt:Date.now()}); else await S.db.collection("brands").doc().set({...data, createdAt:Date.now(), updatedAt:Date.now()}); return true; }
  catch(e){ return denied(e); }
}
async function patchBrand(id, data){ try{ await S.db.collection("brands").doc(id).update({...data, updatedAt:Date.now()}); return true; }catch(e){ return denied(e); } }
async function saveDump(data){ if(!S.db){ toast("Sign in to save changes"); return false; } try{ await S.db.collection("dumps").doc().set({...data, used:false, createdAt:Date.now()}); return true; }catch(e){ return denied(e); } }
async function del(col, id){ try{ await S.db.collection(col).doc(id).delete(); return true; }catch(e){ toast("Couldn't delete. Try again."); return false; } }
async function upload(file){
  if(!S.assets){ toast("Uploads need editor access on this page"); return null; }
  try{ return await S.assets.upload(file); }catch(e){ toast(e?.code==="too_large"?"That file is too big (20 MB max)":"Couldn't upload. Try again."); return null; }
}
async function blobOf(url){ try{ const r=await fetch(url); return r.ok ? await r.blob() : null; }catch(_){ return null; } }

/* ================= panels ================= */
function openPanel(html, wide){ const p=$("panel"); p.className="panel"+(wide===true?" wide":wide?" "+wide:""); delete p.dataset.brand; p.innerHTML=html; $("overlay").hidden=false; p.scrollTop=0; }
function closePanel(){ $("overlay").hidden = true; $("panel").innerHTML = ""; }
$("overlay").addEventListener("click", e => { if(e.target.id==="overlay") closePanel(); });
document.addEventListener("keydown", e => { if(e.key==="Escape" && !$("overlay").hidden) closePanel(); });

