/* drawing */
const _logoCache = {};
function kitLogo(b){
  const u = safeUrl(b?.logo); if(!u) return Promise.resolve(null);
  if(!_logoCache[u]) _logoCache[u] = new Promise(res => { const im = new Image(); im.crossOrigin = "anonymous"; im.onload = () => { try{ const t=document.createElement("canvas"); t.width=t.height=2; t.getContext("2d").drawImage(im,0,0,2,2); t.toDataURL(); res(im); }catch(_){ res(null); } }; im.onerror = () => res(null); im.src = u; });
  return _logoCache[u];
}
function fitLines(ctx, text, maxW, size, maxLines, weight){
  const words = String(text||"").split(/\s+/).filter(Boolean);
  for(let s=size; s>=10; s=Math.floor(s*0.92)){
    ctx.font = `${weight} ${s}px ui-sans-serif,system-ui,-apple-system,"Segoe UI",sans-serif`;
    const lines=[]; let cur="";
    for(const w of words){ const t = cur?cur+" "+w:w; if(ctx.measureText(t).width<=maxW || !cur) cur=t; else { lines.push(cur); cur=w; } }
    if(cur) lines.push(cur);
    if(lines.length<=maxLines && lines.every(l=>ctx.measureText(l).width<=maxW)) return {s, lines};
  }
  return {s:10, lines:[String(text||"").slice(0,40)]};
}
function drawKitImage(b, sp, it, logo){
  const W=sp.w, H=sp.h, cv=document.createElement("canvas"); cv.width=W; cv.height=H; const g=cv.getContext("2d");
  const c1=okColor(b.color,"#3846F0"), c2=okColor(b.color2,c1), ink = lightBg(c1)&&lightBg(c2) ? "#14161F" : "#FFFFFF";
  const gr=g.createLinearGradient(0,0,W,H); gr.addColorStop(0,c1); gr.addColorStop(1,c2); g.fillStyle=gr; g.fillRect(0,0,W,H);
  const m=Math.min(W,H), M=Math.max(W,H);
  g.globalAlpha=.10; g.fillStyle=ink; g.beginPath(); g.arc(W*.92,H*.08,M*.32,0,7); g.fill(); g.beginPath(); g.arc(W*.05,H*1.02,M*.18,0,7); g.fill(); g.globalAlpha=1;
  const mark = (cx,cy,size) => {
    if(logo){ const r=Math.min(size/logo.width,size/logo.height); const w=logo.width*r, h=logo.height*r;
      g.fillStyle="#FFFFFF"; g.beginPath(); g.arc(cx,cy,size*.62,0,7); g.fill(); g.drawImage(logo,cx-w*.42,cy-h*.42,w*.84,h*.84); }
    else { g.fillStyle=ink; g.textAlign="center"; g.textBaseline="middle"; const t=initials(b); g.font=`800 ${size*(t.length>2?.62:.8)}px ui-sans-serif,system-ui,sans-serif`; g.fillText(t,cx,cy+size*.04); }
  };
  if(sp.kind==="icon"){ mark(W/2,H/2,m*.5); return cv; }
  const [sx,sy,sw,sh] = sp.safe || [W*.06,H*.12,W*.88,H*.76];
  const line = it?.line || b.tagline || b.name || "", sub = it?.sub || "";
  g.fillStyle=ink; g.textBaseline="alphabetic";
  if(sw/sh < 1.7){ /* square-ish: stack */
    mark(sx+sw/2, sy+sh*.3, sh*.26); g.textAlign="center";
    const h1=fitLines(g,line,sw*.86,sh*.09,2,800); let y=sy+sh*.62; h1.lines.forEach(l=>{ g.font=`800 ${h1.s}px ui-sans-serif,system-ui,sans-serif`; g.fillText(l,sx+sw/2,y); y+=h1.s*1.12; });
    if(sub){ const h2=fitLines(g,sub,sw*.8,h1.s*.5,2,500); g.globalAlpha=.85; h2.lines.forEach(l=>{ g.font=`500 ${h2.s}px ui-sans-serif,system-ui,sans-serif`; y+=h2.s*.3; g.fillText(l,sx+sw/2,y); y+=h2.s*1.15; }); g.globalAlpha=1; }
    return cv;
  }
  /* wide banner: mark + text; keep clear of the profile picture overlay on the left when needed */
  const right = sp.avoid==="left", ms = Math.min(sh*.62, sw*.12), gap = ms*.45;
  const textW = sw - ms - gap - (right ? sw*.22 : 0);
  const h1=fitLines(g,line,textW,sh*.3,sub?1:2,800), h2=sub?fitLines(g,sub,textW,Math.max(h1.s*.5,sh*.11),1,500):null;
  const blockH = h1.lines.length*h1.s*1.1 + (h2?h2.s*1.5:0);
  const tx = right ? sx+sw : sx+ms+gap, ty = sy + (sh-blockH)/2 + h1.s*.9;
  if(!right) mark(sx+ms/2, sy+sh/2, ms); else mark(sx+sw-ms/2, sy+sh/2, ms);
  g.textAlign = right ? "right" : "left"; const tX = right ? tx-ms-gap : tx;
  let y=ty; h1.lines.forEach(l=>{ g.font=`800 ${h1.s}px ui-sans-serif,system-ui,sans-serif`; g.fillText(l,tX,y); y+=h1.s*1.1; });
  if(h2){ g.globalAlpha=.85; g.font=`500 ${h2.s}px ui-sans-serif,system-ui,sans-serif`; g.fillText(h2.lines[0],tX,y+h2.s*.35); g.globalAlpha=1; }
  return cv;
}
const cvBlob = cv => new Promise(r => cv.toBlob(r,"image/png"));
const slug = s => String(s||"").toLowerCase().replace(/[^a-z0-9]+/g,"-").replace(/^-|-$/g,"").slice(0,40) || "file";

/* tiny zip (store, no compression) */
const _crcT = (()=>{ const t=new Uint32Array(256); for(let n=0;n<256;n++){ let c=n; for(let k=0;k<8;k++) c = c&1 ? 0xEDB88320^(c>>>1) : c>>>1; t[n]=c>>>0; } return t; })();
const crc32 = u => { let c=0xFFFFFFFF; for(let i=0;i<u.length;i++) c=_crcT[(c^u[i])&255]^(c>>>8); return (c^0xFFFFFFFF)>>>0; };
function makeZip(files){ /* [{name, data:Uint8Array}] */
  const enc=new TextEncoder(), parts=[], central=[]; let off=0;
  for(const f of files){
    const nm=enc.encode(f.name), d=f.data, crc=crc32(d), h=new DataView(new ArrayBuffer(30));
    h.setUint32(0,0x04034b50,true); h.setUint16(4,20,true); h.setUint16(6,0x0800,true); h.setUint16(8,0,true); h.setUint16(10,0,true); h.setUint16(12,0x5B71,true); h.setUint32(14,crc,true); h.setUint32(18,d.length,true); h.setUint32(22,d.length,true); h.setUint16(26,nm.length,true);
    parts.push(new Uint8Array(h.buffer), nm, d);
    const c=new DataView(new ArrayBuffer(46)); c.setUint32(0,0x02014b50,true); c.setUint16(4,20,true); c.setUint16(6,20,true); c.setUint16(8,0x0800,true); c.setUint16(14,0x5B71,true); c.setUint32(16,crc,true); c.setUint32(20,d.length,true); c.setUint32(24,d.length,true); c.setUint16(28,nm.length,true); c.setUint32(42,off,true);
    central.push(new Uint8Array(c.buffer), nm); off += 30+nm.length+d.length;
  }
  const cs = central.reduce((a,x)=>a+x.length,0), e=new DataView(new ArrayBuffer(22));
  e.setUint32(0,0x06054b50,true); e.setUint16(8,files.length,true); e.setUint16(10,files.length,true); e.setUint32(12,cs,true); e.setUint32(16,off,true);
  return new Blob([...parts,...central,new Uint8Array(e.buffer)]);
}

async function saveFile(filename, data){
  if(!S.downloads){ toast("Saving files isn't available here"); return false; }
  try{ await S.downloads.save({filename, data}); return true; }
  catch(e){ if(e?.code!=="declined") toast(e?.code==="rate_limited"?"One save at a time. Try again in a moment.":"Couldn't save that file."); return false; }
}

/* UI */
