const AD_PF = [["meta","Meta (Instagram + Facebook)","https://adsmanager.facebook.com"],["google","Google Ads","https://ads.google.com"],["youtube","YouTube (Google Ads)","https://ads.google.com"],["linkedin","LinkedIn Ads","https://www.linkedin.com/campaignmanager"],["x","X Ads","https://ads.x.com"],["snapchat","Snapchat Ads","https://ads.snapchat.com"],["reddit","Reddit Ads","https://ads.reddit.com"],["amazon","Amazon Ads","https://advertising.amazon.in"],["flipkart","Flipkart Ads","https://advertising.flipkart.com"],["blinkit","Blinkit Ads","https://brands.blinkit.com"],["swiggy","Swiggy / Instamart Ads","https://partner.swiggy.com"],["zomato","Zomato Ads","https://www.zomato.com/partners"],["googlebusiness","Google Maps / Local","https://ads.google.com"],["other","Other",""]];
