const AD_PG = {meta:"instagram", google:"website", youtube:"youtube", linkedin:"linkedin", x:"x", snapchat:"snapchat", reddit:"reddit", amazon:"amazon", flipkart:"flipkart", blinkit:"blinkit", swiggy:"swiggy", zomato:"zomato", googlebusiness:"googlebusiness", other:"other"};
