function adCopyHtml(cp){
  if(!cp?.headlines?.length) return "";
  const field = (label, k, arr) => arr.map((v,i)=>`<div class="ktxt"><div class="ktl"><span>${label} ${arr.length>1?i+1:""}</span><span class="kcount">${String(v).length}</span><button class="lnk" data-kcopy>Copy</button></div><div class="kv" contenteditable="plaintext-only" data-ac="${k}|${i}">${esc(v)}</div></div>`).join("");
  return field("Headline","headlines",cp.headlines) + field("Ad text","primary",cp.primary||[])
    + `<div class="ktxt"><div class="ktl"><span>Button</span><button class="lnk" data-kcopy>Copy</button></div><div class="kv" contenteditable="plaintext-only" data-ac="cta">${esc(cp.cta||"")}</div></div>`
    + `<div class="ktxt"><div class="ktl"><span>Image line</span></div><div class="kv" contenteditable="plaintext-only" data-ac="visual">${esc(cp.visual||"")}</div></div>`
    + (cp.keywords?.length?`<div class="ktxt"><div class="ktl"><span>Keywords</span><button class="lnk" data-kcopy>Copy</button></div><div class="kv">${esc(cp.keywords.join(", "))}</div></div>`:"")
    + (cp.budgetTip?`<div class="muted" style="font-size:12.5px">💡 ${esc(cp.budgetTip)}</div>`:"");
}

/* ---------- Messages ---------- */
const MSG_KIND = [["dm","DM"],["comment","Comment"],["review","Review"],["whatsapp","WhatsApp"],["email","Email"],["other","Other"]];
const MSG_ST = [["new","New"],["replied","Replied"],["lead","Lead"],["won","Won"],["closed","Closed"],["spam","Spam"]];
function renderMessages(){
  const box=$("msgBox"); if(!box) return;
  const mStatus = S.mod.mStatus, inB = m => inScope(m.brandId);
  const all = S.messages.filter(inB).sort((a,b)=>(b.receivedAt||0)-(a.receivedAt||0));
  const cnt = k => all.filter(m=>k==="open"?(m.status==="new"||m.status==="lead"):m.status===k).length;
  const list = all.filter(m=>mStatus==="all"||(mStatus==="open"?(m.status==="new"||m.status==="lead"):m.status===mStatus));
  box.innerHTML = `<div class="mod-bar"><button class="btn primary sm" id="msgAdd">+ Add messages</button></div>
  <div class="chips">${[["open","To handle"],["new","New"],["lead","Leads"],["won","Won"],["replied","Replied"],["all","All"]].map(([k,l])=>`<button class="chip" data-mst="${k}" aria-pressed="${mStatus===k}">${l}<span class="n">${k==="all"?all.length:cnt(k)}</span></button>`).join("")}</div>
  <div class="msgs">${list.length?list.map(msgRow).join(""):`<div class="banner">${all.length?"Nothing here.":"No messages yet. Press + Add messages and paste DMs, comments or reviews, or drop a screenshot of your inbox. Claude sorts them and drafts replies in each brand's voice."}</div>`}</div>`;
  box.querySelectorAll("[data-mst]").forEach(x=>x.onclick=()=>{ S.mod.mStatus=x.dataset.mst; renderMessages(); });
  $("msgAdd").onclick = () => msgAddPanel();
  box.querySelectorAll("[data-msg]").forEach(x=>x.onclick=()=>msgPanel(x.dataset.msg));
}
function msgRow(m){
  const b=brandById(m.brandId), st=MSG_ST.find(s=>s[0]===m.status)||MSG_ST[0];
  return `<button class="msg" data-msg="${esc(m.id)}">${pg(m.platform||"other")}<span class="tt"><b>${esc(m.from||"Someone")}<small> · ${esc(b?.name||"")} · ${esc((MSG_KIND.find(k=>k[0]===m.kind)||["","Message"])[1])}</small></b><small class="mt">${esc(String(m.text||"").slice(0,140))}</small></span><span class="pill st-${esc(m.status||"new")}">${st[1]}</span></button>`;
}
function msgAddPanel(){
  openPanel(`<div class="panel-h"><h2>Add messages</h2><button class="btn ghost" data-close aria-label="Close">✕</button></div>
  <form class="form" onsubmit="return false">
    <div class="field"><label for="ma_brand">Brand</label><select id="ma_brand">${opts(S.brands.slice().sort((a,b)=>a.name.localeCompare(b.name)).map(x=>[x.id,x.name]),S.brand||"")}</select></div>
    <div class="field"><label for="ma_pf">Channel</label><select id="ma_pf"></select></div>
    <div class="field full"><label for="ma_text">Paste one or many messages, comments or reviews</label><textarea id="ma_text" rows="7" placeholder="@riya_k: Do you ship to Pune? What's the price for 2?&#10;@rahul: Loved the reel!"></textarea></div>
    <div class="field full"><label for="ma_img">Or a screenshot of the inbox or comments</label><input type="file" id="ma_img" accept="image/*" ${S.sample?"":"disabled"}></div>
  </form>
  <div class="panel-foot"><div class="status-line" id="maStatus"></div><div class="actions"><button class="btn" data-close>Cancel</button><button class="btn primary" id="maGo" ${S.sample?"":"disabled"}>✦ Sort and draft replies</button></div></div>`);
  const fill = () => { const b=brandById($("ma_brand").value); $("ma_pf").innerHTML = opts([...chans(b).map(c=>[c.platform,cmeta(c).label]),["other","Other"]].filter((x,i,a)=>a.findIndex(y=>y[0]===x[0])===i), ""); };
  fill(); $("ma_brand").onchange = fill;
  $("maGo").onclick = async () => {
    const b=brandById($("ma_brand").value), text=$("ma_text").value.trim(), img=$("ma_img").files[0];
    if(!text && !img) return toast("Paste messages or add a screenshot");
    $("maGo").disabled=true; $("maStatus").textContent="Claude is sorting and drafting…";
    const prompt = `${BASE_VOICE}

You manage the inbox for this brand. Split the input into separate incoming messages (ignore the brand's own replies). For each one, sort it and draft a reply in the brand's voice that a human can send as is. Be helpful and specific; ask one clear question if needed to move a buyer forward. Never invent prices, stock, delivery times, policies or offers that aren't in the brand info: say you'll confirm instead. For hate or spam, status "spam" and reply "".
Brand (JSON): ${JSON.stringify(brandBrief(b))}
Channel: ${pf($("ma_pf").value).label}
${text?`Messages:\n${text.slice(0,8000)}`:"Messages: read them from the screenshot."}
Reply with only JSON array: [{"from":"name or handle","text":"their message","kind":"dm|comment|review|whatsapp|email|other","status":"new|lead|spam","intent":"question|buying|complaint|praise|collab|support|other","reply":"draft reply"}]`;
    try{ const out = await S.sample.json(prompt, {modelTier:"default", ...(img?{images:[img]}:{})});
      const arr = (Array.isArray(out)?out:[]).filter(x=>x&&x.text).slice(0,60); let n=0;
      for(const x of arr){ if(await setDoc("messages", null, {brandId:b.id, platform:$("ma_pf").value, from:String(x.from||"").slice(0,80), text:String(x.text).slice(0,4000), kind:MSG_KIND.some(k=>k[0]===x.kind)?x.kind:"dm", status:["new","lead","spam"].includes(x.status)?x.status:"new", intent:String(x.intent||""), reply:String(x.reply||""), receivedAt:Date.now(), createdAt:Date.now()})) n++; else break; }
      closePanel(); toast(n?`${n} message${n>1?"s":""} added with draft replies`:"No messages found"); if(location.hash!=="#messages") location.hash="messages";
    }catch(_){ $("maStatus").textContent="Claude couldn't read that. Try again."; $("maGo").disabled=false; }
  };
}
