/* ===== Google Drive sync: DistributionOS/<Brand>/{Brain, Brand kit, Generations/YYYY-MM, Videos, Analyses} ===== */
const GDRIVE = "Google Drive", DRIVE_ROOT_SEED = "";
const FOLDER_MT = "application/vnd.google-apps.folder";
const dHash = s => { let h=5381; s=String(s); for(let i=0;i<s.length;i++) h=((h<<5)+h+s.charCodeAt(i))|0; return (h>>>0).toString(36)+"."+s.length; };
const dName = s => String(s||"Untitled").replace(/[\\/:*?"<>|\n\r\t]+/g," ").replace(/\s+/g," ").trim().slice(0,120) || "Untitled";
const driveOn = () => uiGet("driveAuto","1")==="1";
S.drive = S.drive || {};
function driveState(key){ return S.drive[key] || (S.drive[key] = {folders:{}, files:{}}); }
async function driveSave(key){ if(!S.db) return; const st=driveState(key); try{ await S.db.collection("drive").doc(key).set({folders:st.folders, files:st.files, rootId:st.rootId||null, lastSync:st.lastSync||null, updatedAt:Date.now()}); }catch(_){} }
async function dCall(tool, input){
  if(!S.mcp) throw {code:"no_mcp"};
  const r = await S.mcp.callTool(GDRIVE, tool, input, {cache:false});
  const p = r?.payload; return (p && typeof p==="object") ? p : (()=>{ try{ return JSON.parse(textOf(r)); }catch(_){ return {}; } })();
}
async function dFolder(st, key, title, parentId){
  if(st.folders[key]) return st.folders[key];
  const q = `title = '${title.replace(/\\/g,"\\\\").replace(/'/g,"\\'")}' and parentId = '${parentId}' and mimeType = '${FOLDER_MT}' and trashed = false`;
  let id = null;
  try{ const f = await dCall("search_files", {query:q, excludeContentSnippets:true, pageSize:1}); id = (f.files||[])[0]?.id || null; }catch(e){ if(e?.code && e.code!=="tool_error") throw e; }
  if(!id){ const c = await dCall("create_file", {title, contentMimeType:FOLDER_MT, parentId}); id = c.id; }
  if(!id) throw {code:"no_id"};
  st.folders[key] = id; return id;
}
async function dPut(st, key, h, spec){
  const old = st.files[key]; if(old && old.h===h) return false;
  const body = {title:spec.title, parentId:spec.parentId, contentMimeType:spec.mime};
  if(spec.text!=null) body.textContent = spec.text; else body.base64Content = spec.b64;
  if(spec.raw) body.disableConversionToGoogleType = true;
  let c; try{ c = await dCall("create_file", body); }catch(e){ if(["not_granted","server_not_connected","needs_reauth","approval_required","consent_required","capability_disabled","not_in_manifest","no_mcp"].includes(e?.code)) throw e; S.driveErr=(e?.message||e?.code||"error")+" ("+spec.title+")"; S.driveFails=(S.driveFails||0)+1; return false; }
  if(!c?.id){ S.driveFails=(S.driveFails||0)+1; return false; }
  st.files[key] = {id:c.id, h, url:c.viewUrl||""};
  if(old?.id){ try{ await dCall("trash_file", {fileId:old.id}); }catch(_){} }
  return true;
}
const blobB64 = blob => new Promise((res,rej)=>{ const r=new FileReader(); r.onload=()=>res(String(r.result).split(",")[1]||""); r.onerror=rej; r.readAsDataURL(blob); });
const csvRow = a => a.map(v=>{ const s=String(v??""); return /[",\n]/.test(s) ? `"${s.replace(/"/g,'""')}"` : s; }).join(",");
function brainMd(b){
  const br=b.brain||{}, L=v=>Array.isArray(v)?v.map(x=>"- "+(typeof x==="object"?Object.values(x).join(" · "):x)).join("\n"):(typeof v==="object"?Object.entries(v).map(([k,x])=>`- ${k}: ${x}`).join("\n"):String(v));
  let md=`# ${b.name}\n\n${b.tagline?`_${b.tagline}_\n\n`:""}Group: ${b.group||""} · Industry: ${b.industry||""}${b.website?` · ${b.website}`:""}\n\n`;
  if(b.voice) md+=`## Voice\n${b.voice}\n\n`;
  [["summary","Summary"],["audience","Audience"],["personality","Personality"],["tone","Tone"],["pillars","Content pillars"],["hooks","Hooks"],["dos","Do"],["donts","Don't"],["vocabulary","Vocabulary"],["hashtags","Hashtags"],["language","Language"],["ctaStyle","CTA style"],["visual","Visual"]].forEach(([k,t])=>{ const v=br[k]; if(v && (!Array.isArray(v)||v.length) && (typeof v!=="object"||Object.keys(v).length)) md+=`## ${t}\n${L(v)}\n\n`; });
  md+=`## Channels\n`+(chans(b).map(c=>`- ${cmeta(c).label}: ${c.handle||""} ${c.url||""} (${+c.cadence||0}/wk)`).join("\n")||"- none yet")+"\n";
  return md;
}
function postMd(p, b, c){
  const e=p.edit||{};
  return `# ${p.title||"Untitled"}\n\n${p.date||"No date"} · ${c?cmeta(c).label:(p.platform||"")} · ${p.format||""} · ${p.status||""}${p.link?`\n\nPublished: ${p.link}`:""}${p.heygen?.url?`\n\nAvatar video: ${p.heygen.url}`:""}\n\n${e.style?`Style: ${e.style} · ${e.aspect||""} · ${e.lengthSec||""}s\n\n`:""}${p.notes||""}\n`;
}
function anaMd(a){
  const x=a.analysis||{}; return `# ${x.title||"Video analysis"}\n\nSource: ${a.url}\n\n${x.platform||""} · ${x.stats||""} · ${x.lengthSec||""}s · ${x.style||""}\n\n## Hook\n${x.hook||""}\n\n## Beats\n${(x.beats||[]).map(t=>`- ${t.t}: ${t.what}`).join("\n")}\n\n## Pacing, audio, text\n- ${x.pacing||""}\n- ${x.audio||""}\n- ${x.text||""}\n\n## Why it works\n${(x.why||[]).map(w=>"- "+w).join("\n")}\n\n## Hook / brief\n${x.brief||""}\n`;
}
let driveBusy=false, driveTimer=null;
function driveSoon(){ if(!driveOn() || !S.drive._loaded || !S.drive._all?.rootId) return; clearTimeout(driveTimer); driveTimer=setTimeout(()=>driveSync({quiet:true}), 20000); }
function driveMsg(t){ const el=$("drvStatus"); if(el) el.textContent=t; }
async function driveSync(opt={}){
  if(driveBusy) return; if(!S.mcp){ if(!opt.quiet) driveMsg("Connect Google Drive in ⚙ Settings → Connectors first."); return; }
  driveBusy=true; let n=0, fails=0; const t0=Date.now(); S.driveFails=0; S.driveErr="";
  const all=driveState("_all"); all.rootId = all.rootId || DRIVE_ROOT_SEED;
  try{
    // check the root folder still exists (by id, not search: search can lag behind new folders)
    let alive=false; try{ const m=await dCall("get_file_metadata",{fileId:all.rootId, excludeContentSnippets:true}); alive=!!m?.id && !m.trashed; }catch(e){ if(e?.code && !["tool_error","upstream_error"].includes(e.code)) throw e; }
    if(!alive){ const c=await dCall("create_file",{title:"HyperMixer", contentMimeType:FOLDER_MT, parentId:"root"}); if(!c?.id) throw {code:"no_id"}; all.rootId=c.id; all.folders={}; all.files={}; S.brands.forEach(b=>{ S.drive[b.id]={folders:{},files:{}}; }); }
    const root=all.rootId, allF=await dFolder(all,"all","_All brands",root);
    const chanOf2=(b,id)=>chans(b).find(c=>c.id===id);
    const cal=[["Date","Brand","Channel","Format","Status","Title","Published link"]].concat(S.posts.slice().sort((a,b)=>String(a.date||"").localeCompare(String(b.date||""))).map(p=>{ const b=brandById(p.brandId), c=b&&chanOf2(b,p.channelId); return [p.date||"",b?.name||"",c?cmeta(c).label:(p.platform||""),p.format||"",p.status||"",p.title||"",p.link||""]; }));
    const calCsv=cal.map(csvRow).join("\n"); if(await dPut(all,"calendar",dHash(calCsv),{title:"Content calendar",parentId:allF,mime:"text/csv",text:calCsv})) n++;
    await driveSave("_all");
    const subCsv=[["Service","Brands","Platform","Plan","Price","Currency","Cycle","Status","Renews","Manage URL","Notes"]].concat((S.subs||[]).map(s=>[s.service,(s.brandIds||[]).map(i=>brandById(i)?.name||i).join(", "),s.platform,s.plan,s.price,s.currency,s.cycle,s.status,s.renews||s.nextCharge||"",s.manageUrl,s.notes])).map(csvRow).join("\n");
    if(await dPut(all,"subs",dHash(subCsv),{title:"Accounts and subs",parentId:allF,mime:"text/csv",text:subCsv})) n++;
    await driveSave("_all");
    const brands=S.brands.slice().sort((a,b)=>(a.order??999)-(b.order??999)); let bi=0;
    for(const b of brands){
      bi++; driveMsg(`Syncing ${b.name} (${bi}/${brands.length})…`);
      const st=driveState(b.id);
      try{
        const bf=await dFolder(st,"brand",dName(b.name),root);
        const md=brainMd(b); if(await dPut(st,"brain",dHash(md),{title:"Brain",parentId:bf,mime:"text/markdown",text:md})) n++;
        const K=kitOf(b.id), kitIds=Object.keys(K);
        if(kitIds.length || safeUrl(b.logo)){
          const kf=await dFolder(st,"kit","Brand kit",bf);
          if(safeUrl(b.logo)){ const h=dHash(b.logo); if(st.files.logo?.h!==h){ try{ const bl=await (await fetch(b.logo)).blob(); if(await dPut(st,"logo",h,{title:"Logo",parentId:kf,mime:bl.type||"image/png",b64:await blobB64(bl),raw:true})) n++; }catch(_){ fails++; } } }
          if(kitIds.length){
            let txt=`# ${b.name} · Profile kit\n\n`;
            for(const cid of kitIds){ const it=K[cid], c=chanOf2(b,cid)||{id:cid,platform:it.platform}, sp=kitSpec(c);
              txt+=`## ${cmeta(c).label}\n`+(it.line?`**Banner line:** ${it.line}\n\n`:"")+(it.sub?`**Banner sub:** ${it.sub}\n\n`:"")+sp.t.map(t=>it.f?.[t.k]?`**${t.label}:**\n${it.f[t.k]}\n\n`:"").join("");
              for(const im of sp.i){ const key=`kit|${cid}|${im.k}`, h=dHash(JSON.stringify([it.line,it.sub,b.name,b.color,b.color2,b.logo,b.monogram,im.w,im.h]));
                if(st.files[key]?.h===h) continue;
                try{ const blob=await cvBlob(drawKitImage(b,im,it,await kitLogo(b))); if(blob && await dPut(st,key,h,{title:`${cmeta(c).label} - ${im.label} ${im.w}x${im.h}.png`,parentId:kf,mime:"image/png",b64:await blobB64(blob),raw:true})) n++; }catch(e){ fails++; if(e?.code==="not_granted"||e?.code==="server_not_connected") throw e; }
              } }
            if(await dPut(st,"kittext",dHash(txt),{title:"Bios and profile text",parentId:kf,mime:"text/markdown",text:txt})) n++;
          }
        }
        const posts=S.posts.filter(p=>p.brandId===b.id);
        if(posts.length){ const gf=await dFolder(st,"gen","Generations",bf);
          for(const p of posts){ const m=(p.date||"Undated").slice(0,7), mf=await dFolder(st,"gen|"+m,m,gf), c=chanOf2(b,p.channelId), md2=postMd(p,b,c);
            if(await dPut(st,"post|"+p.id,dHash(md2+m),{title:dName(`${p.date?p.date+" ":""}${c?cmeta(c).label:(p.platform||"")} - ${p.title||"Untitled"}`).slice(0,110),parentId:mf,mime:"text/markdown",text:md2})) n++; } }
        const vids=(S.renders||[]).filter(r=>r.brandId===b.id && safeUrl(r.output?.assetUrl));
        if(vids.length){ const vf=await dFolder(st,"vid","Videos",bf);
          for(const r of vids){ const key="vid|"+r.id, h=dHash(r.output.assetUrl); if(st.files[key]?.h===h) continue;
            try{ const bl=await (await fetch(r.output.assetUrl)).blob(); if(bl.size>40e6) throw {code:"too_big"}; if(await dPut(st,key,h,{title:dName(`${r.channel||""} - ${r.title||"Video"}`)+".mp4",parentId:vf,mime:bl.type||"video/mp4",b64:await blobB64(bl),raw:true})) n++; }catch(e){ fails++; } } }
        await driveSave(b.id);
      }catch(e){ await driveSave(b.id); if(["not_granted","server_not_connected","no_mcp","needs_reauth","approval_required","consent_required","capability_disabled","not_in_manifest"].includes(e?.code)) throw e; fails++; }
    }
    const anas=Object.entries(S.analyses||{}).filter(([,a])=>a.status==="done" && a.analysis);
    if(anas.length){ const af=await dFolder(all,"ana","Analyses",allF); for(const [id,a] of anas){ const md3=anaMd(a); if(await dPut(all,"ana|"+id,dHash(md3),{title:dName(a.analysis.title||a.url),parentId:af,mime:"text/markdown",text:md3})) n++; } }
    all.lastSync=Date.now(); await driveSave("_all");
    fails += S.driveFails||0;
    driveMsg(n||fails ? `Synced ${n} file${n===1?"":"s"}${fails?`, ${fails} failed, they retry next sync${S.driveErr?": "+S.driveErr:""}`:""} · ${Math.round((Date.now()-t0)/1000)}s` : "Everything is already in Drive.");
    if(!opt.quiet && n) toast(`Saved ${n} file${n===1?"":"s"} to Google Drive`);
  }catch(e){
    const c=e?.code; driveMsg(c==="approval_required"||c==="consent_required" ? "Drive needs your OK for this page. Press Sync now and choose Always allow when asked." : c==="server_not_connected"||c==="needs_reauth" ? "Google Drive isn't connected for this page. Connect it in ⚙ Settings → Connectors, then press Sync now." : c==="not_granted" ? "Drive access was declined for this page. Allow it from the page's Permissions menu." : "Sync stopped: "+(e?.message||c||"unknown error")+". Press Sync now to resume.");
  }finally{ driveBusy=false; try{ await driveSave("_all"); }catch(_){} }
}
function drivePanel(){
  const all=S.drive._all||{}, url=all.rootId?`https://drive.google.com/drive/folders/${all.rootId}`:"";
  openPanel(`<div class="panel-h"><h2>☁️ Google Drive</h2><button class="btn ghost" data-close aria-label="Close">✕</button></div>
  <p class="muted" style="margin-top:0">Everything lives in <b>DistributionOS</b> in your Drive, one folder per brand: Brain, Brand kit (logo, profile pictures, banners, bios), Generations by month and Videos. <b>_All brands</b> holds the content calendar, accounts sheet and reel analyses. Passwords are never synced.</p>
  <div style="display:flex;gap:8px;flex-wrap:wrap;align-items:center;margin:14px 0">
    <button class="btn primary" id="drvGo">Sync now</button>
    ${url?`<a class="btn" href="${url}" target="_blank" rel="noopener">Open folder ↗</a>`:""}
    <label style="display:flex;gap:6px;align-items:center;font-size:14px"><input type="checkbox" id="drvAuto" ${driveOn()?"checked":""}> Auto-sync new work</label>
  </div>
  <div id="drvStatus" class="muted" style="font-size:13px">${all.lastSync?`Last synced ${new Date(all.lastSync).toLocaleString()}`:"Not synced yet."}</div>`);
  $("panel").querySelector("[data-close]").onclick=closePanel;
  $("drvGo").onclick=()=>driveSync();
  $("drvAuto").onchange=e=>{ uiSet("driveAuto", e.target.checked?"1":"0"); toast(e.target.checked?"Auto-sync on":"Auto-sync off"); };
}

