/* ================= HyperMixer app overrides =================
   The board above is shared with the Claude-hosted version. These replace the
   parts that assumed a renderer on the owner's Mac or a password lock. */
function lockCheck(){ const l=$("lock"); if(l) l.hidden=true; }
function macBar(){
  const active = S.renders.filter(r=>r.status==="queued"||r.status==="rendering").length;
  const lastBatch = S.renders.filter(r=>r.status!=="cancelled").sort((a,b)=>(b.requestedAt||0)-(a.requestedAt||0))[0];
  const batch = lastBatch ? S.renders.filter(r=>r.status!=="cancelled" && (lastBatch.batch ? r.batch===lastBatch.batch : (r.status==="queued"||r.status==="rendering"||(r.updatedAt||0) > Date.now()-6*3600e3))) : [];
  const bDone = batch.filter(r=>r.status==="done").length, bFail = batch.filter(r=>r.status==="failed").length;
  const bPart = batch.filter(r=>r.status==="rendering").reduce((a,r)=>a+Math.min(99,Math.max(0,+r.progress||0))/100,0);
  const pct = batch.length ? Math.round((bDone+bFail+bPart)/batch.length*100) : 0;
  const overall = batch.length && (active || bDone < batch.length) ? `<div class="pbar-wrap"><div class="pbar-h"><b>${bDone} of ${batch.length} videos ready</b><span>${pct}%${bFail?` · ${bFail} failed`:""}</span></div><div class="pbar"><i style="width:${pct}%"></i></div></div>` : "";
  return `<div class="macbar on"><span class="dot"></span><div style="min-width:0;flex:1"><b>${active?`Rendering ${active} video${active===1?"":"s"} in this tab`:"Ready to render"}</b><div class="muted" style="font-size:12px">${active?"Keep this tab open until they're done.":"Queued videos start on their own."}</div></div>${active?`<button class="btn danger" id="cancelAll">✕ Cancel all ${active}</button>`:""}</div>${overall}`;
}
