function setLive(on, text){ $("live").classList.toggle("on",on); $("liveText").textContent=text; }
setupCollapsibles(); wireMemory(); showView(location.hash.slice(1)); render();
(async () => {
  const c = window.claude;
  const offline = msg => { setLive(false,msg[0]); $("banner").hidden=false; $("banner").textContent=msg[1]; S.gotB=S.gotP=true; render(); };
  if(!c?.use) return offline(["Couldn't start","Reload the page to try again."]);
  const db = await c.use("db");
  if(!db) return offline(["Storage unavailable","This browser blocked on-device storage. Turn off private mode and reload."]);
  S.db = db;
  const timer = setTimeout(()=>{ if(!S.gotB||!S.gotP) setLive(false,"Still connecting…"); }, 10000);
  const ok = () => { if(S.gotB&&S.gotP){ clearTimeout(timer); setLive(true,"Saved on this device"); } };
  const onErr = () => { clearTimeout(timer); setLive(false,"Connection lost. Reload to reconnect."); };
  db.collection("brands").onSnapshot(snap => { S.brands = snap.docs.filter(d=>d.exists).map(d=>({...d.data(), id:d.id, name:String(d.data().name||"Untitled")})); S.gotB=true; ok(); render(); const pb=$("panel").dataset.brand; if(pb && $("srcList") && !reading.has(pb)) renderSources(pb); }, onErr);
  db.collection("posts").onSnapshot(snap => { S.posts = snap.docs.filter(d=>d.exists).map(d=>({...d.data(), id:d.id})); S.gotP=true; ok(); render(); driveSoon(); hgResume(); }, onErr);
  db.collection("dumps").onSnapshot(snap => { S.dumps = snap.docs.filter(d=>d.exists).map(d=>({...d.data(), id:d.id})); renderStats(); renderBrands(); const l=$("dumpList"), bid=$("panel").dataset.brand; if(l && bid){ l.innerHTML = dumpsOf(bid).map(dumpItem).join("") || `<div class="muted" style="font-size:13px">Nothing dumped yet.</div>`; } }, ()=>{});
  c.use("sample").then(async s => { if(s){ S.sample=s; $("planBtn").hidden=false; try{ const L=await s.limits(); S.imgCaps = L?.images || null; }catch(_){ S.imgCaps=null; } } }).catch(()=>{});
  c.use("assets").then(a => { S.assets = a || null; }).catch(()=>{});
  c.use("downloads").then(d => { S.downloads = d || null; const pb=$("panel").dataset.brand; if(pb && $("kitBox")) renderKit(pb); }).catch(()=>{});
  db.collection("kits").onSnapshot(snap => { const k={}; snap.docs.filter(d=>d.exists).forEach(d=>k[d.id]=d.data()); S.kits=k; driveSoon(); const pb=$("panel").dataset.brand, bx=$("kitBox"); if(pb && bx && !bx.contains(document.activeElement) && !S.kitBusy) renderKit(pb); }, ()=>{});
  db.collection("media").onSnapshot(snap => { S.media = snap.docs.filter(d=>d.exists).map(d=>({...d.data(), id:d.id})); }, ()=>{});
  db.collection("subs").onSnapshot(snap => { S.subs = snap.docs.filter(d=>d.exists).map(d=>({...d.data(), id:d.id})); renderStats(); }, ()=>{});
  db.collection("analyses").onSnapshot(snap => { const s={}; snap.docs.filter(d=>d.exists).forEach(d=>s[d.id]=d.data()); S.analyses=s; driveSoon(); const L=S.lastAnalysis; if(L){ const d=s["a_"+srcKey(L.url).slice(0,80)]; if(d?.status==="done" && d.analysis && !L.deep && !document.activeElement?.closest?.("#lbOut")){ renderAnalysis(L.url, {...L, ...d.analysis, deep:true}); } } }, ()=>{});
  db.collection("setups").onSnapshot(snap => { const s={}; snap.docs.filter(d=>d.exists).forEach(d=>s[d.id]=d.data()); S.setups=s; const pb=$("panel").dataset.brand, bx=$("kitBox"); if(pb && bx && !bx.contains(document.activeElement) && !S.kitBusy) renderKit(pb); }, ()=>{});
  db.collection("campaigns").onSnapshot(snap => { S.campaigns = snap.docs.filter(d=>d.exists).map(d=>({...d.data(), id:d.id})); renderAds(); renderAnalytics(); }, ()=>{});
  db.collection("messages").onSnapshot(snap => { S.messages = snap.docs.filter(d=>d.exists).map(d=>({...d.data(), id:d.id})); const n=S.messages.filter(m=>m.status==="new").length; $("msgCount").textContent = n?" "+n:""; renderMessages(); renderAnalytics(); }, ()=>{});
  db.collection("drive").onSnapshot(snap => { if(driveBusy) return; snap.docs.filter(d=>d.exists).forEach(d=>{ const x=d.data(); S.drive[d.id]={folders:x.folders||{}, files:x.files||{}, rootId:x.rootId||undefined, lastSync:x.lastSync}; }); S.drive._loaded=true; }, ()=>{ S.drive._loaded=true; });
  db.collection("styles").onSnapshot(snap => { S.styles = snap.docs.filter(d=>d.exists).map(d=>({...d.data(), id:d.id})); }, ()=>{});
  db.collection("meta").onSnapshot(snap => { const m={}; snap.docs.filter(d=>d.exists).forEach(d=>m[d.id]=d.data()); S.meta=m; lockCheck(); renderAnalytics(); renderMap(); if($("macBarBox")){ $("macBarBox").innerHTML = macBar(); wireMacBar(); } }, ()=>{});
  db.collection("renders").onSnapshot(snap => { S.renders = snap.docs.filter(d=>d.exists).map(d=>({...d.data(), id:d.id})); updateQueueBtn(); renderMap(); driveSoon(); renderBoard(); if($("macBarBox") && ![...$("panel").querySelectorAll("video")].some(v=>!v.paused) && !$("panel").querySelector("[data-sure]")){ const st=$("panel").scrollTop; queuePanel(); $("panel").scrollTop=st; } }, ()=>{});
  c.use("mcp").then(m => { S.mcp = m || null; }).catch(()=>{});
})();
